const events = $input.all().map(item => item.json).filter(event => event.id);
const getTime = (value) => value ? new Date(value).getTime() : NaN;
const busy = events.map(event => ({
  start: getTime(event.start?.dateTime ?? event.start?.date ?? event.start),
  end: getTime(event.end?.dateTime ?? event.end?.date ?? event.end)
})).filter(range => Number.isFinite(range.start) && Number.isFinite(range.end));
const now = Date.now();
const bogotaNow = new Date(now - 5 * 60 * 60 * 1000);
const base = new Date(Date.UTC(bogotaNow.getUTCFullYear(), bogotaNow.getUTCMonth(), bogotaNow.getUTCDate()));
const formatter = new Intl.DateTimeFormat('es-CO', {
  timeZone: 'America/Bogota', weekday: 'short', day: '2-digit', month: 'short', hour: 'numeric', minute: '2-digit'
});
const slots = [];
for (let dayOffset = 0; dayOffset < 14; dayOffset++) {
  const day = new Date(base.getTime() + dayOffset * 86400000);
  const weekday = day.getUTCDay();
  if (weekday === 0 || weekday === 6) continue;
  for (let hour = 9; hour < 17; hour++) {
    for (const minute of [0, 30]) {
      const start = new Date(Date.UTC(day.getUTCFullYear(), day.getUTCMonth(), day.getUTCDate(), hour + 5, minute));
      const end = new Date(start.getTime() + 30 * 60000);
      if (start.getTime() < now + 2 * 60 * 60 * 1000) continue;
      const overlaps = busy.some(range => start.getTime() < range.end && end.getTime() > range.start);
      if (!overlaps) slots.push({ start: start.toISOString(), end: end.toISOString(), label: formatter.format(start) });
    }
  }
}
return [{ json: { ok: true, timezone: 'America/Bogota', duration_minutes: 30, slots: slots.slice(0, 24) } }];
